545	// Start-run confirmation. Starting a run spends real money (model calls, Crustdata credits) and
546	// talks to Dodo Payments in test mode, so it never starts on one click: a native modal <dialog>
547	// (focus trapped by the browser, Esc cancels, focus returns to the opener) states what will run,
548	// the Dodo mode, and the USD cap as `notary serve` reports it — or that it reports none. Nothing
549	// here is assumed: the integration lines and the cap come from GET /api/health.
550	import { useEffect, useId, useRef } from "react";
551	import type { HealthResponse } from "../../../../core/src/schema";
552	import { Button } from "../../ui";
553	import "../approvals/approvals.css";
554	
555	export type StartRunFacts = {
556	  /** "Queue run (guarded)", "Notarize Dodo Payments", … */
557	  label: string;
558	  /** The integration lines /api/health reported, verbatim. */
559	  integrations: { name: string; label: string }[];
560	  /** The USD cap line: from /api/health when it reports one, else "no USD cap reported". */
561	  usdCap: string;
562	};
563	
564	/** What the dialog says, from the health response only (pure, unit-tested). */
565	export function startRunFacts(label: string, health: HealthResponse | null): StartRunFacts {
566	  const integrations = (health?.integrations ?? [])
567	    .filter((i) => i.name === "llm" || i.name === "crustdata" || i.name === "dodo")
568	    .map((i) => ({ name: i.name === "llm" ? "Models" : i.name === "dodo" ? "Dodo Payments" : "Crustdata", label: i.label }));
569	  // /api/health carries no budget fields today; a cap is never assumed (NOTARY_MAX_USD lives in .env).
570	  const cap = (health as (HealthResponse & { usdCap?: unknown }) | null)?.usdCap;
571	  const usdCap =
572	    typeof cap === "number" && Number.isFinite(cap)
573	      ? `$${cap} (NOTARY_MAX_USD)`
574	      : "No USD cap reported — /api/health does not expose one, so this page cannot confirm a spending limit.";
575	  return { label, integrations, usdCap };
576	}
