641	            <div key={i.name}>
642	              <dt>{i.name}</dt>
643	              <dd>{i.label}</dd>
644	            </div>
645	          ))}
646	        </dl>
647	        {error && (
648	          <p className="approval-error" role="alert">
649	            {error}
650	          </p>
651	        )}
652	        <div className="approval-dialog-actions">
653	          <Button type="button" variant="secondary" onClick={() => ref.current?.close()} disabled={busy}>
