655	          </Button>
656	          <Button type="submit" disabled={busy} autoFocus>
657	            {busy && <span className="ui-spinner" aria-hidden="true" />}
658	            {busy ? "Starting…" : "Start the run"}
659	          </Button>
660	        </div>
661	      </form>
662	    </dialog>
663	  );
664	}
